#!/bin/bash
set -euo pipefail
DOMAIN="${DOMAIN:-www.keyoapi.xyz}"
mkdir -p /opt/ai-relay/static/brand
echo "" | base64 -d > /opt/ai-relay/static/brand/keyo-docs.html
echo "" | base64 -d > /opt/ai-relay/static/brand/keyo-home.html
cat >/etc/caddy/Caddyfile <<EOF
${DOMAIN} {
	encode gzip

	handle_path /brand/* {
		root * /opt/ai-relay/static/brand
		file_server
	}

	handle {
		reverse_proxy 127.0.0.1:3000
	}
}
EOF
caddy validate --config /etc/caddy/Caddyfile
systemctl reload caddy
echo "==> headers"
curl -sI "https://${DOMAIN}/brand/keyo-docs.html" | head -n 10
wc -c /opt/ai-relay/static/brand/keyo-docs.html
echo DONE
